export type Tarefa = { id: number, titulo: string, concluida: boolean }

export type Filtro = { estado: string, termo?: string }

type Criterio = (tarefa: Tarefa) => boolean

const criteriosDeEstado = new Map<string, Criterio>([
  ['todas', () => true],
  ['abertas', (tarefa) => tarefa.concluida === false],
  ['concluidas', (tarefa) => tarefa.concluida === true]
])

const normalizarTermo = (termo: string | undefined): string =>
  (termo ?? '').trim().toLowerCase()

const criterioDeTermo = (termo: string): Criterio => (tarefa) =>
  tarefa.titulo.toLowerCase().includes(termo)

export function filtrarTarefas(tarefas: Tarefa[], filtro: Filtro): Tarefa[] {
  const criterioEstado = criteriosDeEstado.get(filtro.estado)
  if (criterioEstado === undefined) {
    throw new Error('Estado inválido')
  }

  const termo = normalizarTermo(filtro.termo)
  const criterios: Criterio[] = termo === ''
    ? [criterioEstado]
    : [criterioEstado, criterioDeTermo(termo)]

  return tarefas.filter((tarefa) => criterios.every((criterio) => criterio(tarefa)))
}
